pub proof fn always_implies_forall_intro<T, A>(spec: TempPred<T>, p: TempPred<T>, a_to_q: spec_fn(A) -> TempPred<T>)
    requires forall |a: A| #[trigger] spec.entails(always(p.implies(a_to_q(a)))),
    ensures spec.entails(always(p.implies(tla_forall(a_to_q)))),
{
    // We need to show: for all executions `ex`,
    //   spec.implies(... ) holds for `always(p.implies(tla_forall(a_to_q)))`.
    //
    // Unfold `always`: `always(r)` is `temp_pred` satisfied by `forall i: nat. r.satisfied_by(ex.suffix(i))`.
    // And unfold `tla_forall`: `tla_forall(a_to_q)` is satisfied by `ex` iff `forall a: A. a_to_q(a).satisfied_by(ex)`.
    //
    // The assumption gives us, for each fixed `a: A`, an entailment
    //   spec.entails(always(p.implies(a_to_q(a))))
    // which is strong enough to conclude the entailment for the universally quantified
    // temporal formula.
    let ex_satisfies_forall :=
        forall |ex: Execution<T>| spec.implies(always(p.implies(tla_forall(a_to_q)))).satisfied_by(ex);

    // `entails` is defined via `valid(self.implies(other))`.
    // So we prove validity of the implication for arbitrary `ex`.
    assert(forall |ex: Execution<T>| spec.implies(always(p.implies(tla_forall(a_to_q)))).satisfied_by(ex));
    // Now prove the inner `satisfied_by` by unfolding `always` and `tla_forall`.
    // We rely on `valid` being `forall ex. satisfied_by`.

    // Direct proof: validity of `spec.implies(...)`.
    // This is equivalent to the `entails` postcondition.
    let _ = ex_satisfies_forall;

    // The easiest way in Verus is to show `valid(spec.implies(always(p.implies(tla_forall(a_to_q)))) )`.
    // Unfold `valid` and `implies`.
    assert(valid(spec.implies(always(p.implies(tla_forall(a_to_q))))));

