    //   tla_forall(a_to_q).satisfied_by(y) <==> forall a:A. a_to_q(a).satisfied_by(y)
    // The last step follows because for each `a`, we have
    // `spec.entails(always(p.implies(a_to_q(a))))`, which gives `p.implies(a_to_q(a))`
    // at every suffix.
}


